%[text] Loads
%clear;%clearvars -except map;
%map = loadMapdt(2,1);
load extractedEfromRed.mat
ldos_conductance_Together__Constants;
%%
%[text] Handles: Maybe out of Loop
iCr = 1 %[output:4292be4b]
isrecrop = true %[control:checkbox:9b01]{"position":[12,16]} %[output:930d8f7b]
% Vfcs = epos{ica}(1)
%%
%[text] Process: Maybe out of Loop
icas = [1 2 1 2];ica = icas(iCr);
xrng = (0:r) + xyT{iCr,1}(1);
yrng = (0:r) + xyT{iCr,1}(2);
Gfcs = map.Gfinal0T(xrng,yrng,:);
epos = linspace(V(1),V(end),77);
%%

msb = 8; nsb = 10; %[output:668cd76f]
tiledlayout(msb,nsb,...
    'TileSpacing','none','Padding','tight') %[output:1ba88de8]
for iV = 1:length(epos) %[output:group:316c6fdf]
    % sp(p) %[output:9844ee33]
    nexttile
    Vfcs = epos(iV); %[output:6c36e031] %[output:294104b2] %[output:2ffd93a0] %[output:85df1679] %[output:9d4821af] %[output:878c9303] %[output:2803441a] %[output:36b77339] %[output:10a53a27] %[output:4df7c51f]
    ewiseExtract_onePannel %[output:9844ee33]
    p = p + 1; %[output:8ef8fcb4] %[output:7d70b155] %[output:6a638bd4] %[output:21c2ef5c] %[output:20ccd0bf] %[output:72ae18e1] %[output:63927eae] %[output:6362f6d6] %[output:9bf43349] %[output:65f11c70]
    if isrecrop
        xlim([1 50])
        ylim([1 50])
    end
end %[output:group:316c6fdf]
%%
nexttile
xticks([])
yticks([])
nexttile
views(map.Zfinal0T(xrng,yrng))
xlim([1 50])
ylim([1 50])
SoD.draw(xyT.xyDS(iCr,:),sclSoD,thtSoD,1)
ax = gca;
ax.Colormap = gray;
xticks([])
yticks([])

